  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    # Verify all nodes present
    node_set = set(nodes)
    for node in core:
        if node not in node_set:
            raise ValueError(f'Core distance node {node} not in nodes list')
    for u, v, d in distances:
        if u not in node_set or v not in node_set:
            raise ValueError(f'Distance pair ({u},{v}) contains unknown node')

    n = len(nodes)
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))

    # Sort deterministically: by weight, then by u, then by v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
